import{_ as e,o as n,c as i,a2 as o}from"./chunks/framework.CDpkVv68.js";const u=JSON.parse('{"title":"Habilidades y conocimiento","description":"","frontmatter":{},"headers":[],"relativePath":"es/game-design/skills-and-knowledge.md","filePath":"es/game-design/skills-and-knowledge.md"}'),s={name:"es/game-design/skills-and-knowledge.md"};function r(t,a,d,c,l,p){return n(),i("div",null,[...a[0]||(a[0]=[o('<h1 id="skills-and-knowledge" tabindex="-1">Habilidades y conocimiento <a class="header-anchor" href="#skills-and-knowledge" aria-label="Enlace permanente a &quot;Habilidades y conocimiento&quot;">​</a></h1><p><strong>Estado del diseño: Aceptado para la división de funciones; Experimental para la divulgación de Anatomy de Stage 2A aprobada el 2026-10-02; Propuesto para las políticas más amplias de conocimiento. Implementación: habilidades heredadas más inspección cualitativa de Anatomy.</strong></p><p>Anatomy informa <strong>dónde</strong>: estructura y estado corporal. Arms Lore informa <strong>cómo/con qué</strong>: equipo, protección y vulnerabilidades. Tactics informa <strong>cuándo</strong>: oportunidades y comprensión táctica. La habilidad de arma informa la <strong>ejecución</strong>. Las decisiones del jugador deberían importar junto con la inversión del personaje.</p><p>Una base de límite de habilidades de aproximadamente 700 puntos expresa coste de oportunidad, no una instrucción para cambiar la configuración actual. Comprobaciones exactas, entrenamiento, precisión de divulgación, umbrales y contrapartidas no están terminados.</p><p>Stage 2A añade información localizada a la habilidad Anatomy existente. La regla experimental aprobada el 2026-10-02 conserva la comprobación existente de Anatomy en un rango 0–100 y su comportamiento de aumento/enfriamiento: el éxito revela los siete estados cualitativos; el fallo no revela estado local. Anatomy no divulga cifras exactas de integridad, trauma, armadura ni probabilidades de apuntado. La información existente de fuerza/destreza/stamina no cambia. El experimento se aplica solo en UOR cuando está activo, a jugadores humanos vivos, conectados y sin transformación, a ocho casillas o menos, visibles y en LOS. Tactics no cambia hasta que existan oportunidades tácticas.</p><p>La información privilegiada de pruebas está separada del conocimiento del personaje: no consume, entrena ni exige Anatomy, ni amplía lo que revela esa habilidad.</p><p><strong>Brecha:</strong> la precisión/progresión final de divulgación, los sistemas Arms Lore y Tactics y la legibilidad en juego siguen sin validarse. La regla Stage 2A es una política de prototipo descartable, no balance definitivo. Contrato de evaluación · Preguntas abiertas.</p><h2 id="proposed-magic-roles" tabindex="-1">Funciones mágicas — Propuesto <a class="header-anchor" href="#proposed-magic-roles" aria-label="Enlace permanente a &quot;Funciones mágicas — Propuesto&quot;">​</a></h2><p>El <a href="/Syrolands-Public/es/game-design/magic.html">rediseño mágico v0.1</a> separa ejecución de Magery, conocimiento permanente de hechizos, Mastery, aprendizaje institucional, ingeniería de Inscription y Meditation/concentración. Conserva híbridos sin clases en lugar de añadir una habilidad por disciplina/afinidad. Sus <a href="/Syrolands-Public/es/game-design/magic.html#use-based-gain-and-structured-teaching">objetivos de entrenamiento</a> y el <a href="/Syrolands-Public/es/game-design/magic.html#normal-and-focused-cast">lanzamiento focalizado basado en Anatomy</a> mantienen estado Propuesto; no cambian la regla aprobada de divulgación de Anatomy de Stage 2A ni la configuración actual de habilidades.</p><h2 id="proposed-environmental-expertise" tabindex="-1">Conocimiento ambiental — Propuesto <a class="header-anchor" href="#proposed-environmental-expertise" aria-label="Enlace permanente a &quot;Conocimiento ambiental — Propuesto&quot;">​</a></h2><p>La <a href="/Syrolands-Public/es/game-design/living-world.html#knowledge-professions-and-traces">propuesta de mundo vivo</a> da a Lumberjacking, Mining, Tracking, Camping y Magery posibles funciones en la interacción material y el conocimiento ambiental cualitativo. Las reglas de divulgación y las posibles nuevas profesiones siguen sin resolverse; aquí no cambian habilidades, límites ni políticas existentes de Anatomy.</p><h2 id="proposed-profession-progression-and-techniques" tabindex="-1">Progresión profesional y técnicas — Propuesto <a class="header-anchor" href="#proposed-profession-progression-and-techniques" aria-label="Enlace permanente a &quot;Progresión profesional y técnicas — Propuesto&quot;">​</a></h2><p>El <a href="/Syrolands-Public/es/game-design/characters/skills-and-skillcap.html">marco de habilidades del personaje</a> centraliza ahora límites/aumentos, capacidad útil con habilidad baja y enseñanza; la <a href="/Syrolands-Public/es/game-design/characters/progression.html">progresión del personaje</a> define la filosofía general y las <a href="/Syrolands-Public/es/game-design/characters/techniques-and-specialization.html">técnicas</a>, la especialización aprendida. El <a href="/Syrolands-Public/es/game-design/professions/profession-system.html">Sistema de profesiones</a> conserva diarios artesanales, producción y reputación. Todos los nuevos rangos, aumentos, enseñanza y reglas de creación mantienen estado <strong>Propuesto</strong>; la configuración actual y el comportamiento aprobado de Anatomy no cambian.</p><p>Habilidad, técnica aprendida, camino profesional e identidad en el mundo son distintos. <a href="/Syrolands-Public/es/game-design/professions/carpentry.html#bowmaking-and-fletching">Bowmaking / Fletching</a> se propone como camino técnico de Carpentry/Archery con oficios de apoyo opcionales, no como habilidad independiente. Esta página resume funciones, <strong>no es una lista exhaustiva conciliada de habilidades</strong>. No se aprueba eliminar habilidades, reasignar ID ni migrar personajes. El <a href="/Syrolands-Public/es/game-design/professions/profession-system.html#open-questions-and-reconciliation-required">registro de conciliación</a> registra la brecha del listado y los candidatos opcionales anteriores Forestry/Geology/Engineering.</p><h2 id="batch-02-character-framework" tabindex="-1">Marco del personaje de Batch 02 <a class="header-anchor" href="#batch-02-character-framework" aria-label="Enlace permanente a &quot;Marco del personaje de Batch 02&quot;">​</a></h2><p>Los <a href="/Syrolands-Public/es/game-design/characters/character-creation.html">orígenes</a> proponen historias iniciales sin clases permanentes. Las <a href="/Syrolands-Public/es/game-design/characters/stats.html">estadísticas</a> proponen una respuesta básica y aportes acotados de estadísticas. Bowcraft heredado y el comportamiento de límites/aumentos/creación aún necesitan conciliación. Revisar la presión de inversión en Anatomy, Tactics y Healing en el diseño futuro de combate; las funciones existentes y la divulgación aprobada siguen intactas.</p><h2 id="batch-03-combat-skill-review" tabindex="-1">Revisión de habilidades de combate de Batch 03 <a class="header-anchor" href="#batch-03-combat-skill-review" aria-label="Enlace permanente a &quot;Revisión de habilidades de combate de Batch 03&quot;">​</a></h2><p><strong>Propuesto:</strong> ampliar Anatomy como interpretación útil del trauma local y las regiones vulnerables, con posibles sinergias de Healing y caza/desuello. Esto no cambia la divulgación aceptada y acotada de arriba. <a href="/Syrolands-Public/es/game-design/combat/targeting.html#proposed-targeting-factors-and-knowledge">Selección de objetivos</a> define los factores propuestos de selección.</p><p>Tactics sigue siendo una habilidad marcial cuyo papel necesita revisión más allá de una contribución plana de daño universalmente obligatoria: decisiones de ataque, postura/posicionamiento, técnicas avanzadas y ejecución táctica son usos candidatos. La escala heredada de daño no es el rediseño final. La <a href="/Syrolands-Public/es/game-design/combat/overview.html#combat-foundation-integration">diversidad de configuraciones</a> y los <a href="/Syrolands-Public/es/game-design/combat/damage.html#proposed-injuries-and-healing">límites de Healing</a> siguen siendo propuestas, sin un nuevo conjunto obligatorio de habilidades.</p>',19)])])}const g=e(s,[["render",r]]);export{u as __pageData,g as default};
